head.script:
scwin.onpageload = function() {

};


scwin.trigger1_onclick = function(e) {
    var val = inputcal1.getDisabled();
     console.log(val);

    if ( val ==false){
        inputcal1.setDisabled(true);
    }else 
    {
        inputcal1.setDisabled(false);
    }
};

scwin.trigger2_onclick = function(e) {
    //debugger;
   var val2 = inputcal2.getDisabled();
   console.log(val2);

    if ( val2 ==false){
        inputcal2.setDisabled(true);
    }else 
    {
        inputcal2.setDisabled(false);
    }
};

scwin.checkVal = function() {
    var test = WebSquare.wUnit.getDomById('inputcal1_calendar');

    return test === null;
};

scwin.unitTest = function () {
    //Unit 
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputcal1_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
};

scwin.unitTest();
